"""Report strongly guided model repair and preserve tested literal patch."""
import json,xml.etree.ElementTree as ET,ast,textwrap,difflib,os,hashlib
from pathlib import Path
H=Path(__file__).resolve().parent;O=H.parent
def main():
    evaluated=json.loads((H/'evaluated.json').read_text());groups={}
    for name,run in evaluated['runs'].items():
        assert run['evidence']['complete'];tests=list(ET.parse(run['execution']['report']).getroot().iter('testcase'));groups[name]={'passed':sum(not any(t.find(k) is not None for k in ['failure','error','skipped']) for t in tests),'total':len(tests),'accepted':run['evidence']['accepted']}
    robust=json.loads((H/'differential-result.json').read_text());previous=json.loads((O/'gemma-feedback-v4/evaluated.json').read_text());tenacity=next(r for r in previous if r['id']=='tenacity-new-v2');assert all(q['evidence']['accepted'] for q in tenacity['runs'].values())
    summary={'packaging':groups,'packaging_all_pass':all(q['accepted'] for q in groups.values()),'packaging_passed':sum(q['passed'] for q in groups.values()),'packaging_total':sum(q['total'] for q in groups.values()),'additional_differential_names':robust['tested_names'],'differential_differences':len(robust['differences']),'previous_tenacity_passed':159,'human_structural_guidance':True,'published_or_submitted':False}
    (H/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
    case=next(c for c in json.loads((O/'gemma-new-repositories-v2/protocol.json').read_text())['cases'] if c['package']=='packaging');parent=next((O.parent/'work/new-upstream-v2'/(case['id']+'-buggy')).iterdir());review=json.loads((H/'reviewed.json').read_text());diff=[]
    for edit in review['edits']:
        old=(parent/edit['file']).read_text(encoding='utf-8');lines=old.splitlines();node=next(n for n in ast.walk(ast.parse(old)) if isinstance(n,ast.FunctionDef) and n.name==edit['function']);lines[node.lineno-1:node.end_lineno]=textwrap.indent(edit['literal_function'],' '*node.col_offset).splitlines();new='\n'.join(lines)+'\n'
        assert hashlib.sha256(new.replace('\n',os.linesep).encode()).hexdigest()==evaluated['patched_source_sha256'][edit['file']]
        diff.extend(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+edit['file'],tofile='b/'+edit['file']))
    (H/'packaging-tested.patch').write_text(''.join(diff),encoding='utf-8');(H/'packaging-LICENSE.txt').write_text(case['license_text'],encoding='utf-8')
    text='Gemma — rozdzielenie przypadków na osobne warunki, 16.10.2026\nAutor: Jacek Adamek\n\nPackaging: 90/90 zadeklarowanych sprawdzeń przechodzi (74 upstream, 7 kontroli przykładów, 9 kontroli niepokazanych modelowi). Dodatkowo zgodność z rzeczywistą przypiętą poprawką upstream dla 1245 różnych nazw plików, bez rozbieżności. Dodatkowy test różnicowy powstał po odczytaniu odpowiedzi modelu; to kontrola odporności, nie uprzednio ukryty benchmark.\n\nNowa odpowiedź zawiera osobną gałąź dla dokładnego pylock.toml i osobne sprawdzanie prefiksu, sufiksu oraz niepustego członu bez kropki. Nie usuwa znaków nowej linii i nie normalizuje nazw. Ciało funkcji pochodzi dosłownie z modelu; nie poprawiano go ręcznie. Lokalny patch ma zweryfikowaną zgodność hashy z przetestowanymi źródłami.\n\nMetoda: jedna generacja, ten sam Gemma E2B Q4_0, temperatura 0, seed 20261016, limit 512 tokenów. Informacja zwrotna jawnie rozdziela dwa dozwolone typy nazw i prosi o osobne gałęzie if, zamiast kolejnego jednowierszowego regexu. To silna pomoc człowieka w strukturze rozwiązania. Nie dostarczono kodu poprawki upstream, ale nie należy przedstawiać wyniku jako samodzielnego odkrycia rozwiązania przez agenta.\n\nTenacity zachowuje wynik 159/159 z poprzedniego etapu; jego kodu nie zmieniano i nie powtarzano bez potrzeby testów. Oba publiczne przypadki mają teraz wygenerowane poprawki przechodzące zadeklarowany zakres testów (łącznie 249/249), po różnej liczbie prób i różnej pomocy. Nie jest to wynik pierwszej próby ani szeroka miara skuteczności modelu. Wszystkie wcześniejsze niepowodzenia pozostają zachowane.\n\nNic nie opublikowano ani nie wysłano. Artykuł, repozytoria i zgłoszenia konkursowe pozostają niezmienione.\n'
    (H/'Wyniki-Gemma.txt').write_text(text,encoding='utf-8');print(summary,flush=True)
if __name__=='__main__':main()
